INSERT INTO public."Branches" ("Name","Address") SELECT 'Sucursal Demo Centro','Calle Demo 10, Centro' WHERE NOT EXISTS (SELECT 1 FROM public."Branches" WHERE "Name"='Sucursal Demo Centro' AND "Address"='Calle Demo 10, Centro');
INSERT INTO public."Tickets" ("BranchId","TechnicianId","ReporterUserId","Title","Description","Status","CreatedAt","UpdatedAt","ScheduledAt","ClientRequestId") SELECT b."Id",t."Id",u."Id",'Demo: revisión de equipo','El equipo no inicia.','Pending',TIMESTAMPTZ '2026-10-01 10:00:00+00',TIMESTAMPTZ '2026-10-01 10:30:00+00',TIMESTAMPTZ '2026-10-01 15:00:00+00','10000000-0000-4000-8000-000000000001' FROM public."Branches" b CROSS JOIN public."Users" t CROSS JOIN public."Users" u WHERE b."Name"='Sucursal Demo Centro' AND b."Address"='Calle Demo 10, Centro' AND t."Username"='tecnico1' AND u."Username"='usuario1' ON CONFLICT ("ClientRequestId") DO NOTHING;
INSERT INTO public."Tickets" ("BranchId","TechnicianId","ReporterUserId","Title","Description","Status","CreatedAt","UpdatedAt","ScheduledAt","ClientRequestId") SELECT b."Id",t."Id",u."Id",'Demo: diagnóstico en curso','La conexión es intermitente.','InProgress',TIMESTAMPTZ '2026-10-01 10:00:00+00',TIMESTAMPTZ '2026-10-01 10:30:00+00',TIMESTAMPTZ '2026-10-01 15:00:00+00','10000000-0000-4000-8000-000000000002' FROM public."Branches" b CROSS JOIN public."Users" t CROSS JOIN public."Users" u WHERE b."Name"='Sucursal Demo Centro' AND b."Address"='Calle Demo 10, Centro' AND t."Username"='tecnico1' AND u."Username"='usuario1' ON CONFLICT ("ClientRequestId") DO NOTHING;
INSERT INTO public."Tickets" ("BranchId","TechnicianId","ReporterUserId","Title","Description","Status","CreatedAt","UpdatedAt","ScheduledAt","ClientRequestId") SELECT b."Id",NULL,u."Id",'Demo: reporte sin asignar','Solicitud nueva pendiente de programación.','Pending',TIMESTAMPTZ '2026-10-01 10:00:00+00',TIMESTAMPTZ '2026-10-01 10:30:00+00',NULL,'10000000-0000-4000-8000-000000000003' FROM public."Branches" b CROSS JOIN public."Users" t CROSS JOIN public."Users" u WHERE b."Name"='Sucursal Demo Centro' AND b."Address"='Calle Demo 10, Centro' AND t."Username"='tecnico1' AND u."Username"='usuario1' ON CONFLICT ("ClientRequestId") DO NOTHING;
INSERT INTO public."Evidences" ("TicketId","Description","CreatedAt") SELECT "Id",'Demo: cableado revisado.',TIMESTAMPTZ '2026-10-01 10:30:00+00' FROM public."Tickets" t WHERE "ClientRequestId"='10000000-0000-4000-8000-000000000002' AND NOT EXISTS (SELECT 1 FROM public."Evidences" WHERE "TicketId"=t."Id" AND "Description"='Demo: cableado revisado.');
INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'CREADO','Ticket demo registrado.',TIMESTAMPTZ '2026-10-01 10:00:00+00',u."Id",'20000000-0000-4000-8000-000000000001',NULL,NULL FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000001' AND u."Username"='usuario1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'PROGRAMADO','Atención demo programada.',TIMESTAMPTZ '2026-10-01 10:05:00+00',u."Id",'30000000-0000-4000-8000-000000000001',TIMESTAMPTZ '2026-10-01 15:00:00+00',NULL FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000001' AND u."Username"='coordinador1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'CREADO','Ticket demo registrado.',TIMESTAMPTZ '2026-10-01 10:00:00+00',u."Id",'20000000-0000-4000-8000-000000000002',NULL,NULL FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000002' AND u."Username"='usuario1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'PROGRAMADO','Atención demo programada.',TIMESTAMPTZ '2026-10-01 10:05:00+00',u."Id",'30000000-0000-4000-8000-000000000002',TIMESTAMPTZ '2026-10-01 15:00:00+00',NULL FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000002' AND u."Username"='coordinador1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'CREADO','Ticket demo registrado.',TIMESTAMPTZ '2026-10-01 10:00:00+00',u."Id",'20000000-0000-4000-8000-000000000003',NULL,NULL FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000003' AND u."Username"='usuario1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
INSERT INTO public."TicketEvents" ("TicketId","EventType","Description","CreatedAt","UserId","ClientRequestId","ScheduledAt","EvidenceId") SELECT t."Id",'EN_ATENCION','Atención demo iniciada.',TIMESTAMPTZ '2026-10-01 10:10:00+00',u."Id",'40000000-0000-4000-8000-000000000001',NULL,NULL FROM public."Tickets" t CROSS JOIN public."Users" u WHERE t."ClientRequestId"='10000000-0000-4000-8000-000000000002' AND u."Username"='tecnico1' ON CONFLICT ("UserId","ClientRequestId") DO NOTHING;
